import React, { useEffect, useMemo, useState } from 'react';
import { ArrowUp, Check, Loader2, Save, Star, Trash2, Users } from 'lucide-react';
import type { CommunityAppDefinition } from './types';

export interface GenericCommunityAppRecord {
  id: string;
  user_id: string;
  record_type: string;
  record_key: string;
  payload: Record<string, any>;
  status: 'active' | 'answered' | 'archived' | 'approved' | 'rejected';
  created_at: string;
  updated_at: string;
}

interface GenericCommunityAppProps {
  definition: CommunityAppDefinition;
  config: Record<string, any>;
  records: GenericCommunityAppRecord[];
  profiles: Record<string, string>;
  currentUser: { id: string; full_name?: string | null; username?: string | null };
  canManage: boolean;
  working: boolean;
  createRecord: (recordType: string, recordKey: string, payload: Record<string, any>) => Promise<GenericCommunityAppRecord | null>;
  upsertRecord: (recordType: string, recordKey: string, payload: Record<string, any>) => Promise<GenericCommunityAppRecord | null>;
  updateRecord: (recordId: string, updates: Partial<Pick<GenericCommunityAppRecord, 'payload' | 'status'>>) => Promise<void>;
}

const inputClass = 'h-12 w-full rounded-2xl border border-white/[0.09] bg-black/25 px-4 text-sm text-white outline-none transition placeholder:text-white/20 focus:border-white/20';
const textareaClass = 'min-h-32 w-full resize-y rounded-2xl border border-white/[0.09] bg-black/25 px-4 py-3 text-sm leading-6 text-white outline-none transition placeholder:text-white/20 focus:border-white/20';
const todayKey = () => new Date().toISOString().slice(0, 10);
const asStrings = (value: unknown) => Array.isArray(value) ? value.map(String).map((item) => item.trim()).filter(Boolean) : [];

function GenericShell({ definition, prompt, children }: { definition: CommunityAppDefinition; prompt: string; children: React.ReactNode }) {
  return (
    <div className="flex min-h-full w-full justify-center px-3 py-5 sm:px-6 sm:py-8 lg:px-10">
      <div className="w-full max-w-6xl">
        <section className="overflow-hidden rounded-[34px] border border-white/[0.09] bg-[radial-gradient(circle_at_10%_0%,color-mix(in_srgb,var(--app-accent)_20%,transparent),transparent_38%),#141416] p-6 shadow-[0_28px_90px_rgba(0,0,0,.28)] sm:p-9" style={{ '--app-accent': definition.accent } as React.CSSProperties}>
          <p className="text-[10px] font-black uppercase tracking-[0.22em]" style={{ color: definition.accent }}>{definition.eyebrow}</p>
          <h2 className="mt-3 max-w-4xl text-3xl font-black tracking-[-0.04em] text-white sm:text-5xl">{definition.title}</h2>
          <p className="mt-4 max-w-3xl text-sm leading-7 text-white/44 sm:text-base">{prompt}</p>
        </section>
        <div className="mt-5">{children}</div>
      </div>
    </div>
  );
}

function EmptyState({ children }: { children: React.ReactNode }) {
  return <div className="rounded-[26px] border border-dashed border-white/[0.1] px-5 py-10 text-center text-sm font-bold text-white/28">{children}</div>;
}

export function GenericCommunityApp({
  definition,
  config,
  records,
  profiles,
  currentUser,
  canManage,
  working,
  createRecord,
  upsertRecord,
  updateRecord,
}: GenericCommunityAppProps) {
  const [textValue, setTextValue] = useState('');
  const [secondaryValue, setSecondaryValue] = useState('');
  const [tagsValue, setTagsValue] = useState('');
  const [numberValue, setNumberValue] = useState('0');
  const [ratingValue, setRatingValue] = useState(0);

  const activeRecords = useMemo(() => records.filter((record) => record.status !== 'archived'), [records]);
  const myRecord = (recordType: string, recordKey: string) => activeRecords.find((record) => record.record_type === recordType && record.record_key === recordKey && record.user_id === currentUser.id);
  const displayName = currentUser.full_name || (currentUser.username ? `@${currentUser.username}` : 'Community member');
  const nameFor = (userId: string) => profiles[userId] || (userId === currentUser.id ? displayName : `Member ${userId.slice(0, 5)}`);
  const prompt = String(config.prompt || definition.description);

  const currentMetric = myRecord('generic_metric', 'current');
  const currentRating = myRecord('generic_rating', 'current');
  const currentProfile = myRecord('generic_profile', 'profile');

  useEffect(() => {
    setTextValue(String(currentProfile?.payload.title || ''));
    setSecondaryValue(String(currentProfile?.payload.detail || currentRating?.payload.comment || ''));
    setTagsValue(asStrings(currentProfile?.payload.tags).join(', '));
    setNumberValue(String(currentMetric?.payload.value ?? 0));
    setRatingValue(Number(currentRating?.payload.rating || 0));
  }, [definition.type, currentMetric?.id, currentMetric?.payload.value, currentProfile?.id, currentRating?.id, currentRating?.payload.rating, currentRating?.payload.comment]);

  if (definition.runtime === 'board') {
    const entries = activeRecords.filter((record) => record.record_type === 'generic_entry');
    const votes = activeRecords.filter((record) => record.record_type === 'generic_vote');
    const myEntries = entries.filter((record) => record.user_id === currentUser.id).length;
    const maxEntries = Math.max(0, Number(config.maxEntriesPerMember || 0));
    const canSubmit = Boolean(config.submissionsOpen) && (maxEntries === 0 || myEntries < maxEntries);
    const voteCount = (entryId: string) => votes.filter((record) => record.record_key === entryId).length;
    const sortedEntries = [...entries].sort((a, b) => voteCount(b.id) - voteCount(a.id) || new Date(b.created_at).getTime() - new Date(a.created_at).getTime());
    return (
      <GenericShell definition={definition} prompt={prompt}>
        <form className="rounded-[30px] border border-white/[0.09] bg-[#151517] p-5 sm:p-7" onSubmit={async (event) => {
          event.preventDefault();
          const contribution = textValue.trim();
          if (!contribution || !canSubmit) return;
          const saved = await createRecord('generic_entry', crypto.randomUUID(), { text: contribution });
          if (saved) setTextValue('');
        }}>
          <label htmlFor={`generic-board-${definition.type}`} className="text-xs font-black text-white/55">Your contribution</label>
          <textarea id={`generic-board-${definition.type}`} value={textValue} onChange={(event) => setTextValue(event.target.value)} maxLength={Math.max(80, Number(config.maxLength || 700))} placeholder={String(config.placeholder || 'Write your contribution…')} className={`${textareaClass} mt-2`} />
          <div className="mt-3 flex flex-wrap items-center justify-between gap-3">
            <span className="text-[10px] font-bold text-white/27">{maxEntries > 0 ? `${myEntries}/${maxEntries} entries used` : `${entries.length} community entries`}</span>
            <button type="submit" disabled={!textValue.trim() || !canSubmit || working} className="inline-flex h-11 items-center justify-center gap-2 rounded-full bg-white px-6 text-xs font-black text-black disabled:opacity-30">{working ? <Loader2 className="h-4 w-4 animate-spin" /> : <Save className="h-4 w-4" />}{String(config.buttonLabel || 'Share')}</button>
          </div>
          {!canSubmit ? <p className="mt-3 text-xs font-bold text-amber-100/45">New contributions are closed or you reached the member limit.</p> : null}
        </form>
        <div className="mt-5 grid gap-3 sm:grid-cols-2">
          {sortedEntries.map((entry) => {
            const voted = Boolean(myRecord('generic_vote', entry.id));
            return (
              <article key={entry.id} className="flex min-h-48 flex-col rounded-[28px] border border-white/[0.08] bg-[#151517] p-5 sm:p-6">
                <p className="flex-1 whitespace-pre-wrap text-sm font-semibold leading-7 text-white/76">{String(entry.payload.text || '')}</p>
                <div className="mt-5 flex items-center justify-between gap-3 border-t border-white/[0.06] pt-4">
                  <span className="truncate text-[11px] text-white/30">{config.showAuthors ? nameFor(entry.user_id) : 'Community member'}</span>
                  <div className="flex items-center gap-2">
                    {config.votingOpen ? <button type="button" disabled={voted || working} onClick={() => upsertRecord('generic_vote', entry.id, { entryId: entry.id })} className="inline-flex h-8 items-center gap-1.5 rounded-full border border-white/[0.09] px-3 text-[10px] font-black text-white/46 disabled:text-emerald-200"><ArrowUp className="h-3.5 w-3.5" />{voteCount(entry.id)}</button> : <span className="text-[10px] font-bold text-white/25">{voteCount(entry.id)} votes</span>}
                    {canManage ? <button type="button" onClick={() => updateRecord(entry.id, { status: 'archived' })} className="grid h-8 w-8 place-items-center rounded-full border border-rose-300/10 text-rose-200/40 hover:bg-rose-400/10" aria-label="Archive contribution"><Trash2 className="h-3.5 w-3.5" /></button> : null}
                  </div>
                </div>
              </article>
            );
          })}
          {sortedEntries.length === 0 ? <div className="sm:col-span-2"><EmptyState>No contributions have been saved yet.</EmptyState></div> : null}
        </div>
      </GenericShell>
    );
  }

  if (definition.runtime === 'tracker') {
    const scoreRecords = activeRecords.filter((record) => record.record_type === 'generic_metric');
    const direction = config.sortDirection === 'asc' ? 1 : -1;
    const ranked = [...scoreRecords].sort((a, b) => direction * (Number(a.payload.value || 0) - Number(b.payload.value || 0)));
    const total = scoreRecords.reduce((sum, record) => sum + Number(record.payload.value || 0), 0);
    const minimum = Number(config.minValue ?? 0);
    const maximum = Math.max(minimum, Number(config.maxValue ?? 10000));
    return (
      <GenericShell definition={definition} prompt={prompt}>
        <div className="grid gap-5 lg:grid-cols-[.72fr_1.28fr]">
          <form className="rounded-[30px] border border-white/[0.09] bg-[#151517] p-6" onSubmit={async (event) => {
            event.preventDefault();
            const value = Math.max(minimum, Math.min(maximum, Number(numberValue)));
            await upsertRecord('generic_metric', 'current', { value });
          }}>
            <p className="text-[10px] font-black uppercase tracking-[0.18em] text-white/28">Your current value</p>
            <label htmlFor={`generic-metric-${definition.type}`} className="mt-5 block text-xs font-black text-white/55">{String(config.metricLabel || 'Progress')}</label>
            <input id={`generic-metric-${definition.type}`} type="number" min={minimum} max={maximum} step={Math.max(0.01, Number(config.step || 1))} value={numberValue} onChange={(event) => setNumberValue(event.target.value)} className={`${inputClass} mt-2`} />
            <button type="submit" disabled={working || !Number.isFinite(Number(numberValue))} className="mt-4 inline-flex h-11 w-full items-center justify-center gap-2 rounded-full bg-white text-xs font-black text-black disabled:opacity-30"><Save className="h-4 w-4" />Save progress</button>
            <div className="mt-5 grid grid-cols-2 gap-2"><div className="rounded-2xl border border-white/[0.07] bg-black/20 p-4"><div className="text-2xl font-black text-white">{scoreRecords.length}</div><div className="mt-1 text-[9px] font-black uppercase tracking-[0.14em] text-white/28">Members</div></div><div className="rounded-2xl border border-white/[0.07] bg-black/20 p-4"><div className="text-2xl font-black text-white">{total.toLocaleString()}</div><div className="mt-1 text-[9px] font-black uppercase tracking-[0.14em] text-white/28">Combined {String(config.unit || '')}</div></div></div>
          </form>
          <section className="rounded-[30px] border border-white/[0.09] bg-[#151517] p-5 sm:p-7">
            <div className="flex items-center justify-between"><h3 className="text-xl font-black text-white">{config.showLeaderboard ? 'Community ranking' : 'Saved progress'}</h3><Users className="h-5 w-5" style={{ color: definition.accent }} /></div>
            <div className="mt-5 space-y-2">{ranked.map((record, index) => <div key={record.id} className="flex items-center gap-3 rounded-2xl border border-white/[0.07] bg-white/[0.03] px-4 py-3"><span className="grid h-8 w-8 shrink-0 place-items-center rounded-full bg-black/25 text-xs font-black text-white/48">{config.showLeaderboard ? index + 1 : '•'}</span><span className="min-w-0 flex-1 truncate text-sm font-bold text-white/68">{nameFor(record.user_id)}</span><span className="text-sm font-black text-white">{Number(record.payload.value || 0).toLocaleString()} <small className="text-white/32">{String(config.unit || '')}</small></span></div>)}{ranked.length === 0 ? <EmptyState>No progress has been saved yet.</EmptyState> : null}</div>
          </section>
        </div>
      </GenericShell>
    );
  }

  if (definition.runtime === 'checklist') {
    const items = asStrings(config.items).slice(0, 50);
    const progress = myRecord('generic_checklist', 'board');
    const checked = new Set<number>(Array.isArray(progress?.payload.checked) ? progress.payload.checked.map(Number) : []);
    const columns = Math.max(1, Math.min(3, Number(config.columns || 2)));
    return (
      <GenericShell definition={definition} prompt={prompt}>
        <section className="rounded-[30px] border border-white/[0.09] bg-[#151517] p-5 sm:p-7">
          <div className="flex items-center justify-between gap-4"><div><p className="text-[10px] font-black uppercase tracking-[0.18em] text-white/28">Personal progress</p><h3 className="mt-2 text-2xl font-black text-white">{config.showProgress ? `${checked.size} of ${items.length} complete` : 'Your checklist'}</h3></div>{config.allowReset && checked.size > 0 ? <button type="button" disabled={working} onClick={() => upsertRecord('generic_checklist', 'board', { checked: [] })} className="rounded-full border border-white/[0.09] px-4 py-2 text-[10px] font-black text-white/40 hover:bg-white/[0.06]">Reset</button> : null}</div>
          <div className="mt-6 grid gap-3" style={{ gridTemplateColumns: `repeat(${columns}, minmax(0, 1fr))` }}>{items.map((item, index) => <button key={`${item}-${index}`} type="button" disabled={working} onClick={() => { const next = new Set(checked); if (next.has(index)) next.delete(index); else next.add(index); void upsertRecord('generic_checklist', 'board', { checked: [...next] }); }} className={`flex min-h-20 items-center gap-3 rounded-[22px] border p-4 text-left text-sm font-bold leading-5 transition ${checked.has(index) ? 'border-emerald-300/25 bg-emerald-400/12 text-emerald-100' : 'border-white/[0.08] bg-black/20 text-white/55 hover:bg-white/[0.06]'}`}><span className="grid h-7 w-7 shrink-0 place-items-center rounded-full border border-current/20">{checked.has(index) ? <Check className="h-4 w-4" /> : null}</span>{item}</button>)}</div>
          {items.length === 0 ? <div className="mt-5"><EmptyState>The owner has not added checklist steps yet.</EmptyState></div> : null}
        </section>
      </GenericShell>
    );
  }

  if (definition.runtime === 'pulse') {
    const pulseRecords = activeRecords.filter((record) => record.record_type === 'generic_pulse');
    const recordKey = config.oncePerDay ? todayKey() : '';
    const participated = config.oncePerDay ? Boolean(myRecord('generic_pulse', recordKey)) : false;
    const count = config.oncePerDay ? pulseRecords.filter((record) => record.record_key === recordKey).length : pulseRecords.length;
    return (
      <GenericShell definition={definition} prompt={prompt}>
        <section className="rounded-[36px] border border-white/[0.09] bg-[#151517] px-6 py-14 text-center sm:px-12 sm:py-20">
          {config.showCount ? <div className="text-6xl font-black tracking-[-0.06em] text-white sm:text-8xl">{count.toLocaleString()}</div> : null}
          <p className="mx-auto mt-4 max-w-lg text-sm leading-6 text-white/38">{participated ? String(config.successMessage || 'Your participation is saved.') : config.oncePerDay ? 'Your action can be saved once today.' : 'Every tap is saved as a participation event.'}</p>
          <button type="button" disabled={working || participated} onClick={() => createRecord('generic_pulse', recordKey || crypto.randomUUID(), { participated: true })} className="mx-auto mt-8 inline-flex h-14 min-w-48 items-center justify-center gap-2 rounded-full bg-white px-7 text-sm font-black text-black shadow-[0_18px_55px_rgba(255,255,255,.12)] disabled:opacity-35">{participated ? <Check className="h-5 w-5" /> : working ? <Loader2 className="h-5 w-5 animate-spin" /> : null}{participated ? 'Saved today' : String(config.actionLabel || 'Count me in')}</button>
        </section>
      </GenericShell>
    );
  }

  if (definition.runtime === 'rating') {
    const ratings = activeRecords.filter((record) => record.record_type === 'generic_rating');
    const scale = Math.max(3, Math.min(10, Number(config.scale || 5)));
    const average = ratings.length > 0 ? ratings.reduce((sum, record) => sum + Number(record.payload.rating || 0), 0) / ratings.length : 0;
    const comment = secondaryValue;
    return (
      <GenericShell definition={definition} prompt={prompt}>
        <div className="grid gap-5 lg:grid-cols-[.78fr_1.22fr]">
          <form className="rounded-[30px] border border-white/[0.09] bg-[#151517] p-6" onSubmit={async (event) => { event.preventDefault(); if (ratingValue < 1) return; await upsertRecord('generic_rating', 'current', { rating: ratingValue, comment: comment.trim() }); }}>
            <div className="flex flex-wrap gap-2">{Array.from({ length: scale }, (_, index) => index + 1).map((value) => <button key={value} type="button" onClick={() => setRatingValue(value)} className={`grid h-11 min-w-11 place-items-center rounded-2xl border px-2 text-xs font-black transition ${ratingValue >= value ? 'border-amber-300/30 bg-amber-400/12 text-amber-100' : 'border-white/[0.08] bg-black/20 text-white/32'}`} aria-label={`Rate ${value} out of ${scale}`}><Star className="h-4 w-4" fill={ratingValue >= value ? 'currentColor' : 'none'} /></button>)}</div>
            <div className="mt-3 flex justify-between text-[10px] font-bold text-white/28"><span>{String(config.lowLabel || 'Low')}</span><span>{String(config.highLabel || 'High')}</span></div>
            {config.allowComment ? <textarea value={comment} onChange={(event) => setSecondaryValue(event.target.value)} maxLength={Math.max(80, Number(config.maxLength || 700))} placeholder="Add optional context…" className={`${textareaClass} mt-5`} /> : null}
            <button type="submit" disabled={working || ratingValue < 1} className="mt-4 inline-flex h-11 w-full items-center justify-center gap-2 rounded-full bg-white text-xs font-black text-black disabled:opacity-30"><Save className="h-4 w-4" />Save rating</button>
          </form>
          <section className="rounded-[30px] border border-white/[0.09] bg-[#151517] p-6"><div className="flex items-end justify-between gap-4"><div><p className="text-[10px] font-black uppercase tracking-[0.18em] text-white/28">Community response</p><h3 className="mt-2 text-4xl font-black text-white">{config.showAverage && ratings.length > 0 ? average.toFixed(1) : ratings.length}</h3></div><span className="text-xs font-bold text-white/30">{config.showAverage ? `average of ${scale}` : `${ratings.length} ratings`}</span></div><div className="mt-6 space-y-2">{ratings.filter((record) => String(record.payload.comment || '').trim()).slice(0, 12).map((record) => <div key={record.id} className="rounded-2xl border border-white/[0.07] bg-black/20 p-4"><div className="flex items-center justify-between"><span className="text-xs font-black text-white/58">{nameFor(record.user_id)}</span><span className="text-xs font-black text-amber-200">{Number(record.payload.rating || 0)}/{scale}</span></div><p className="mt-2 text-sm leading-6 text-white/42">{String(record.payload.comment)}</p></div>)}{ratings.length === 0 ? <EmptyState>No ratings have been saved yet.</EmptyState> : null}</div></section>
        </div>
      </GenericShell>
    );
  }

  if (definition.runtime === 'directory') {
    const directoryRecords = activeRecords.filter((record) => record.record_type === 'generic_profile');
    const profileTitle = textValue || displayName;
    const profileDetail = secondaryValue;
    return (
      <GenericShell definition={definition} prompt={prompt}>
        <div className="grid gap-5 lg:grid-cols-[.76fr_1.24fr]">
          <form className="rounded-[30px] border border-white/[0.09] bg-[#151517] p-6" onSubmit={async (event) => { event.preventDefault(); const tags = tagsValue.split(',').map((tag) => tag.trim()).filter(Boolean).slice(0, Math.max(1, Number(config.maxTags || 12))); const saved = await upsertRecord('generic_profile', 'profile', { title: profileTitle.trim(), detail: profileDetail.trim(), tags }); if (saved) { setTextValue(profileTitle.trim()); setSecondaryValue(profileDetail.trim()); setTagsValue(tags.join(', ')); } }}>
            <label htmlFor={`generic-profile-title-${definition.type}`} className="text-xs font-black text-white/55">{String(config.nameLabel || 'Display title')}</label><input id={`generic-profile-title-${definition.type}`} value={profileTitle} onChange={(event) => setTextValue(event.target.value)} maxLength={100} className={`${inputClass} mt-2`} />
            <label htmlFor={`generic-profile-detail-${definition.type}`} className="mt-4 block text-xs font-black text-white/55">{String(config.detailLabel || 'Introduction')}</label><textarea id={`generic-profile-detail-${definition.type}`} value={profileDetail} onChange={(event) => setSecondaryValue(event.target.value)} maxLength={1000} className={`${textareaClass} mt-2`} />
            <label htmlFor={`generic-profile-tags-${definition.type}`} className="mt-4 block text-xs font-black text-white/55">{String(config.tagsLabel || 'Tags')}</label><input id={`generic-profile-tags-${definition.type}`} value={tagsValue} onChange={(event) => setTagsValue(event.target.value)} placeholder="design, ecommerce, video" className={`${inputClass} mt-2`} />
            <button type="submit" disabled={working || !profileTitle.trim()} className="mt-4 inline-flex h-11 w-full items-center justify-center gap-2 rounded-full bg-white text-xs font-black text-black disabled:opacity-30"><Save className="h-4 w-4" />Save card</button>
          </form>
          <section className="rounded-[30px] border border-white/[0.09] bg-[#151517] p-5 sm:p-7"><div className="flex items-center justify-between"><h3 className="text-xl font-black text-white">Community directory</h3><span className="text-xs font-bold text-white/28">{directoryRecords.length} profiles</span></div>{config.showProfiles ? <div className="mt-5 grid gap-3 sm:grid-cols-2">{directoryRecords.map((record) => <article key={record.id} className="rounded-[24px] border border-white/[0.08] bg-black/20 p-5"><h4 className="text-base font-black text-white">{String(record.payload.title || nameFor(record.user_id))}</h4><p className="mt-2 whitespace-pre-wrap text-sm leading-6 text-white/40">{String(record.payload.detail || '')}</p><div className="mt-4 flex flex-wrap gap-1.5">{asStrings(record.payload.tags).map((tag) => <span key={tag} className="rounded-full border border-white/[0.08] px-2.5 py-1 text-[10px] font-bold text-white/38">{tag}</span>)}</div></article>)}{directoryRecords.length === 0 ? <div className="sm:col-span-2"><EmptyState>No profiles have been saved yet.</EmptyState></div> : null}</div> : <div className="mt-5"><EmptyState>The directory is currently hidden by the owner.</EmptyState></div>}</section>
        </div>
      </GenericShell>
    );
  }

  return null;
}
